def P(x, y):
    s = x + y
    # P(x, y) = s*(s+1)/2 + y
    # Since s*(s+1) is always even, integer division // 2 is safe.
    return s * (s + 1) // 2 + y

M = 100
count_odd = 0

for x in range(M):
    for y in range(M):
        val = P(x, y)
        if val % 2 != 0:
            count_odd += 1

print(f"Count N for P(x, y) in 100x100 grid: {count_odd}")

